<?php if (!$rangeRuns): range_empty('No experiment runs', 'No execution has been performed by this application.'); else: ?>
<p class="text-body-sm text-on-surface-variant">Saved records and user-reported parameters/metrics are not trusted execution or validation evidence.</p><div class="overflow-x-auto"><table class="w-full text-left"><thead class="bg-surface-container-high/60 font-label-sm uppercase"><tr><th class="p-3">Run / Name</th><th class="p-3">Recorded status</th><th class="p-3">User-reported Parameters</th><th class="p-3">User-reported Metrics</th><th class="p-3">Created</th></tr></thead><tbody class="divide-y divide-outline-variant/20"><?php foreach ($rangeRuns as $run): ?><tr><td class="p-3 font-code-sm"><?= range_h($run['run_uuid']) ?><p><?= range_h($run['run_name']) ?></p></td><td class="p-3"><?= range_h($run['status']) ?></td><td class="p-3 font-code-sm whitespace-pre-wrap break-all"><?= range_h($run['parameters'] ?? 'No parameters') ?></td><td class="p-3 font-code-sm whitespace-pre-wrap break-all"><?= range_h($run['metrics'] ?? 'No metrics available') ?></td><td class="p-3"><?= range_h($run['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php endif; ?>
